package com.mfg.workflow.entity;import jakarta.persistence.*;import lombok.Getter;import lombok.NoArgsConstructor;import lombok.Setter;import java.time.LocalDateTime;
@Entity @Table(name="wf_cc") @Getter @Setter @NoArgsConstructor public class WfCc{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="instance_id")private Long instanceId;@Column(name="username")private String username;@Column(name="is_read")private Boolean read=false;@Column(name="created_by")private String createdBy;@Column(name="created_at",insertable=false,updatable=false)private LocalDateTime createdAt;@Column(name="read_at")private LocalDateTime readAt;}
